from flask import Flask, request, jsonify
import json
import os

app = Flask(__name__)

# User model with role-based access
class User:
    ALLOWED_FIELDS = ['username', 'email', 'display_name', 'avatar_url']

    def __init__(self, uid):
        self.uid = uid
        self.username = ''
        self.email = ''
        self.display_name = ''
        self.avatar_url = ''
        self.role = 'user'  # user, admin, superadmin
        self.is_active = True
        self.config_path = '/etc/app/default.conf'
        self.ssh_key_path = ''
        self.backup_dir = '/var/backups/app/'

    def to_dict(self):
        return self.__dict__.copy()

# In-memory store
users_db = {}

def load_user(uid):
    if uid not in users_db:
        users_db[uid] = User(uid)
    return users_db[uid]

@app.route('/api/users/<uid>/profile', methods=['PUT'])
def update_profile(uid):
    """Update user profile - accepts JSON body with fields to update"""
    user = load_user(uid)
    data = request.get_json()

    if not data:
        return jsonify({'error': 'No data provided'}), 400

    # Mass assignment: directly set attributes from user input
    # Developer intended to filter but forgot to apply ALLOWED_FIELDS check
    for key, value in data.items():
        if hasattr(user, key):
            setattr(user, key, value)

    return jsonify({'status': 'updated', 'user': user.to_dict()}), 200

@app.route('/api/users/<uid>/export', methods=['POST'])
def export_user_data(uid):
    """Export user data to their configured backup directory"""
    user = load_user(uid)

    export_path = os.path.join(user.backup_dir, f'{uid}_export.json')

    try:
        os.makedirs(os.path.dirname(export_path), exist_ok=True)
        with open(export_path, 'w') as f:
            json.dump(user.to_dict(), f, indent=2)
        return jsonify({'status': 'exported', 'path': export_path}), 200
    except (OSError, PermissionError) as e:
        return jsonify({'error': f'Export failed: {str(e)}'}), 500

@app.route('/api/users/<uid>/config', methods=['GET'])
def read_config(uid):
    """Read user's application config file"""
    user = load_user(uid)

    try:
        with open(user.config_path, 'r') as f:
            content = f.read()
        return jsonify({'config': content}), 200
    except (OSError, FileNotFoundError) as e:
        return jsonify({'error': f'Config read failed: {str(e)}'}), 500

@app.route('/api/admin/users', methods=['GET'])
def list_users():
    """Admin-only endpoint to list all users"""
    # Check if requesting user is admin (simplified)
    auth_uid = request.headers.get('X-User-ID', '')
    auth_user = load_user(auth_uid) if auth_uid else None

    if not auth_user or auth_user.role not in ('admin', 'superadmin'):
        return jsonify({'error': 'Forbidden'}), 403

    return jsonify({'users': [u.to_dict() for u in users_db.values()]}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
